extern crate std;
use super::*;
use soroban_sdk::{testutils::{Address as _, MockAuth, MockAuthInvoke}, vec, IntoVal};
struct Fixture { env:Env, id:Address, treasury:Address, owner:Address, partner:Address, outsider:Address }
impl Fixture {
 fn new()->Self{
  let env=Env::default();env.mock_all_auths();let treasury=Address::generate(&env);let registrar=Address::generate(&env);let owner=Address::generate(&env);let partner=Address::generate(&env);let outsider=Address::generate(&env);
  let id=env.register(ContributorRegistry,(&treasury,&registrar));
  ContributorRegistryClient::new(&env,&id).register_track(&String::from_str(&env,"track"),&owner);
  Self{env,id,treasury,owner,partner,outsider}
 }
 fn client(&self)->ContributorRegistryClient<'_>{ContributorRegistryClient::new(&self.env,&self.id)}
 fn proposal(&self,version:u32)->Proposal{Proposal{track_id:String::from_str(&self.env,"track"),agreement_id:String::from_str(&self.env,"agreement"),version,owner:self.owner.clone(),recipients:vec![&self.env,SplitRecipient{wallet:self.owner.clone(),role:String::from_str(&self.env,"artist"),share_bps:7000},SplitRecipient{wallet:self.partner.clone(),role:String::from_str(&self.env,"producer"),share_bps:3000}],proposal_hash:BytesN::from_array(&self.env,&[version as u8;32]),previous_finalized_hash:BytesN::from_array(&self.env,&[if version==1{0}else{1};32])}}
 fn finalize(&self){let p=self.proposal(1);self.client().respond(&p,&self.owner,&0);self.client().respond(&p,&self.partner,&0);}
}
#[test] fn last_contributor_finalizes_without_treasury(){let f=Fixture::new();let p=f.proposal(1);assert_eq!(f.client().respond(&p,&f.owner,&0).state,0);assert!(f.client().get_finalized_split(&p.track_id).is_none());assert_eq!(f.client().respond(&p,&f.partner,&0).state,1);assert_eq!(f.env.auths().len(),1);assert_eq!(f.env.auths()[0].0,f.partner);assert_ne!(f.env.auths()[0].0,f.treasury);assert_eq!(f.client().get_finalized_split(&p.track_id).unwrap().proposal_hash,p.proposal_hash);}
#[test] fn missing_auth_and_wrong_invocation_cannot_approve(){let f=Fixture::new();let p=f.proposal(1);f.env.mock_auths(&[]);assert!(f.client().try_respond(&p,&f.owner,&0).is_err());f.env.mock_auths(&[MockAuth{address:&f.owner,invoke:&MockAuthInvoke{contract:&f.id,fn_name:"respond",args:(p.clone(),f.owner.clone(),1u32).into_val(&f.env),sub_invokes:&[]}}]);assert!(f.client().try_respond(&p,&f.owner,&0).is_err());assert!(f.client().get_finalized_split(&p.track_id).is_none());}
#[test] fn registration_cannot_be_overwritten_or_forged(){let f=Fixture::new();let t=String::from_str(&f.env,"track");assert_eq!(f.client().try_register_track(&t,&f.outsider),Err(Ok(Error::Ownership)));f.env.mock_auths(&[]);assert!(f.client().try_register_track(&String::from_str(&f.env,"other"),&f.outsider).is_err());assert_eq!(f.client().owner(&t),Some(f.owner));}
#[test] fn outsider_cannot_start_or_respond(){let f=Fixture::new();let p=f.proposal(1);assert_eq!(f.client().try_respond(&p,&f.outsider,&0),Err(Ok(Error::Ownership)));f.client().respond(&p,&f.owner,&0);assert_eq!(f.client().try_respond(&p,&f.outsider,&0),Err(Ok(Error::Contributor)));assert!(f.client().get_finalized_split(&p.track_id).is_none());}
#[test] fn blocked_proposals_cannot_finalize(){for action in [1,2,3]{let f=Fixture::new();let p=f.proposal(1);f.client().respond(&p,&f.owner,&0);let actor=if action==3{&f.owner}else{&f.partner};let closed=f.client().respond(&p,actor,&action);assert_ne!(closed.state,0);assert_eq!(f.client().try_respond(&p,&f.partner,&0),Err(Ok(Error::Closed)));assert!(f.client().get_finalized_split(&p.track_id).is_none());}}
#[test] fn changed_payload_and_invalid_shares_fail(){let f=Fixture::new();let p=f.proposal(1);f.client().respond(&p,&f.owner,&0);let mut changed=p.clone();changed.proposal_hash=BytesN::from_array(&f.env,&[9;32]);assert_eq!(f.client().try_respond(&changed,&f.partner,&0),Err(Ok(Error::Conflict)));changed=p.clone();let mut r=changed.recipients.get(0).unwrap();r.share_bps=1;changed.recipients.set(0,r);assert_eq!(f.client().try_respond(&changed,&f.partner,&0),Err(Ok(Error::Invalid)));}
#[test] fn removed_beneficiary_must_approve_and_old_version_is_immutable(){let f=Fixture::new();f.finalize();let mut p=f.proposal(2);p.recipients=vec![&f.env,SplitRecipient{wallet:f.owner.clone(),role:String::from_str(&f.env,"artist"),share_bps:10000}];assert_eq!(f.client().respond(&p,&f.owner,&0).state,0);assert_eq!(f.client().get_finalized_split(&p.track_id).unwrap().version,1);assert_eq!(f.client().respond(&p,&f.partner,&0).state,1);assert_eq!(f.client().get_finalized_split(&p.track_id).unwrap().version,2);assert_eq!(f.client().get_finalized_version(&p.track_id,&1).unwrap().recipients.len(),2);}
#[test] fn retries_and_concurrent_amendments_cannot_replace_effective_terms(){let f=Fixture::new();f.finalize();let p=f.proposal(1);assert_eq!(f.client().respond(&p,&f.partner,&0).state,1);let p2=f.proposal(2);f.client().respond(&p2,&f.owner,&0);let p3=f.proposal(3);assert_eq!(f.client().try_respond(&p3,&f.owner,&0),Err(Ok(Error::Closed)));f.client().respond(&p2,&f.partner,&0);assert_eq!(f.client().try_respond(&p3,&f.owner,&0),Err(Ok(Error::Version)));assert_eq!(f.client().get_finalized_split(&p.track_id).unwrap().version,2);}
